mapper.sql:
WHERE company_id = #{f.companyId}

	AND distributor_id = #{f.distributorId}


	AND name LIKE CONCAT('%', #{f.nameContains}, '%')


	AND display_time > #{f.displayTimeGt}


	AND (
		(employee_begin_time < #{f.buyTimeBegin} AND employee_end_time < #{f.buyTimeBegin})
		OR (employee_begin_time < #{f.buyTimeEnd} AND employee_end_time < #{f.buyTimeEnd})
		OR (relative_begin_time < #{f.buyTimeBegin} AND relative_end_time < #{f.buyTimeBegin})
		OR (relative_begin_time < #{f.buyTimeEnd} AND relative_end_time < #{f.buyTimeEnd})
	)


	AND (
		employee_begin_time > #{f.buyTimeBegin}
		OR relative_begin_time > #{f.buyTimeBegin}
		OR (employee_begin_time < #{f.buyTimeBegin} AND employee_end_time > #{f.buyTimeBegin})
		OR (relative_begin_time < #{f.buyTimeBegin} AND relative_end_time > #{f.buyTimeBegin})
	)


	AND (
		employee_end_time < #{f.buyTimeEnd}
		OR relative_end_time < #{f.buyTimeEnd}
		OR (employee_begin_time < #{f.buyTimeEnd} AND employee_end_time > #{f.buyTimeEnd})
		OR (relative_begin_time < #{f.buyTimeEnd} AND relative_end_time > #{f.buyTimeEnd})
	)


	AND id IN

		#{aid}




		AND display_time > #{now}
		AND status = 'active'


		AND display_time < #{now}
		AND employee_begin_time > #{now}
		AND (relative_begin_time IS NULL OR relative_begin_time = 0 OR relative_begin_time > #{now})
		AND status = 'active'


		AND (
			employee_begin_time < #{now}
			OR (relative_begin_time > 0 AND relative_begin_time < #{now})
		)
		AND (
			employee_end_time > #{now}
			OR relative_end_time > #{now}
		)
		AND status = 'active'


		AND (
			employee_begin_time < #{now}
			OR relative_begin_time < #{now}
		)
		AND (
			employee_end_time > #{now}
			OR relative_end_time > #{now}
		)
		AND status = 'pending'


		AND (
			(employee_end_time < #{now} AND relative_end_time < #{now})
			OR status = 'over'
		)


		AND status = #{f.statusDbEquals}
